(function () {
  var wrap     = document.currentScript.previousElementSibling;
  var skeleton = wrap.querySelector('.menu-skeleton-local');
  var grid     = wrap.querySelector('.menu-grid-local');

  var PROXY_URL    = "https://menu.restoexp.com/api/proxy/bloom-room/menu";
  var CATEGORIA_ID = "69bd778e152fa0e2a6b70e30";

  function escapeHtml(str) {
    return String(str || "")
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;")
      .replace(/'/g, "&#039;");
  }

  (async function () {
    try {
      var res   = await fetch(PROXY_URL);
      var data  = await res.json();
      var items = data.items || [];

      var filtrados = items.filter(function (item) {
        return (item.fieldData?.["sub-category"] || []).includes(CATEGORIA_ID);
      });

      skeleton.style.display = "none";

      if (!filtrados.length) {
        grid.innerHTML = '<p class="menu-error">No se encontraron platos en esta categoría.</p>';
        return;
      }

      grid.innerHTML = filtrados.map(function (item) {
        var f        = item.fieldData || {};
        var nombre   = f["name"] || "";
        var imageUrl = (f["image-url"] || {}).url || "";

        var precioRaw = (f["price"] || "").toString().trim();
        var precio    = precioRaw.length ?  precioRaw : "";

        var tmp = document.createElement("div");
        tmp.innerHTML = f["description"] || "";
        var descripcion = (tmp.textContent || "").trim();

        return ''
          + '<div class="card-menu-local">'
          +   '<div class="content-style">'
          +     '<div class="image-13">'
          +       (imageUrl ? '<img loading="lazy" alt="' + escapeHtml(nombre) + '" src="' + escapeHtml(imageUrl) + '" class="plato-image-2">' : '')
          +     '</div>'
          +     '<div class="name">'
          +       '<div class="food-name-2">' + escapeHtml(nombre) + '</div>'
          +     '</div>'
          +     '<div class="info">'
          +       (descripcion ? '<div class="description-4">' + escapeHtml(descripcion) + '</div>' : '')
          +       (precio      ? '<div class="precio-2">'      + escapeHtml(precio)      + '</div>' : '')
          +     '</div>'
          +   '</div>'
          + '</div>';
      }).join("");

    } catch (err) {
      skeleton.style.display = "none";
      grid.innerHTML = '<p class="menu-error">No se pudo cargar el menú.</p>';
      console.error("[MenuLoader]", err);
    }
  })();
})();

